package lk.villagecraft.auth;
import lk.villagecraft.users.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final AppUserRepository users; private final PasswordEncoder encoder; private final AuthenticationManager auth; private final JwtService jwt; private final String bootstrapKey;
 public AuthController(AppUserRepository users,PasswordEncoder encoder,AuthenticationManager auth,JwtService jwt,@Value("${app.bootstrap-admin-key:}") String bootstrapKey){this.users=users;this.encoder=encoder;this.auth=auth;this.jwt=jwt;this.bootstrapKey=bootstrapKey;}
 public record Register(@NotBlank @Size(max=120) String name,@Email @NotBlank String email,@Size(min=12,max=100) String password,@NotBlank @Pattern(regexp="CUSTOMER|PRODUCER") String role){}
 public record Login(@Email @NotBlank String email,@NotBlank String password){}
 public record ChangePassword(@NotBlank String currentPassword,@Size(min=12,max=100) String newPassword){}
 public record BootstrapAdmin(@NotBlank String name,@Email @NotBlank String email,@Size(min=12,max=100) String password){}
 @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody Register r){String email=r.email().trim().toLowerCase();if(users.existsByEmailIgnoreCase(email))return ResponseEntity.status(409).body(Map.of("error","Email already registered"));AppUser u=users.save(new AppUser(r.name().trim(),email,encoder.encode(r.password()),r.role()));return ResponseEntity.status(201).body(Map.of("id",u.getId(),"email",u.getEmail(),"role",u.getRole()));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody Login r){try{Authentication a=auth.authenticate(new UsernamePasswordAuthenticationToken(r.email().trim().toLowerCase(),r.password()));AppUser u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return ResponseEntity.ok(Map.of("token",jwt.issue(u),"email",u.getEmail(),"name",u.getFullName(),"role",u.getRole()));}catch(AuthenticationException e){return ResponseEntity.status(401).body(Map.of("error","Invalid email or password"));}}
 @PostMapping("/bootstrap-admin") @Transactional public ResponseEntity<?> bootstrap(@RequestHeader(value="X-Bootstrap-Key",required=false) String supplied,@Valid @RequestBody BootstrapAdmin r){if(bootstrapKey.isBlank()||supplied==null||!java.security.MessageDigest.isEqual(bootstrapKey.getBytes(),supplied.getBytes()))return ResponseEntity.status(403).body(Map.of("error","Bootstrap key is invalid or not configured"));if(users.existsByEmailIgnoreCase(r.email()))return ResponseEntity.status(409).body(Map.of("error","Email already exists"));if(users.findAll().stream().anyMatch(u->u.getRole().equals("ADMIN")))return ResponseEntity.status(409).body(Map.of("error","An administrator already exists"));AppUser u=users.save(new AppUser(r.name().trim(),r.email().trim().toLowerCase(),encoder.encode(r.password()),"ADMIN"));return ResponseEntity.status(201).body(Map.of("id",u.getId(),"email",u.getEmail(),"role",u.getRole()));}
 @PostMapping("/change-password") public ResponseEntity<?> changePassword(Authentication authentication,@Valid @RequestBody ChangePassword r){AppUser u=users.findByEmailIgnoreCase(authentication.getName()).orElseThrow();if(!encoder.matches(r.currentPassword(),u.getPasswordHash()))return ResponseEntity.status(400).body(Map.of("error","Current password is incorrect"));u.setPasswordHash(encoder.encode(r.newPassword()));users.save(u);return ResponseEntity.ok(Map.of("status","password_changed"));}
}
